                min_c, max_c = min(cols), max(cols)

                # locate the 2
                two_pos = None
                for r, c in cells:
                    if grid[r][c] == 2:
                        two_pos = (r, c)
                        break

                # (the problem guarantees exactly one 2 per component)
                components.append({
                    'cells': cells,
                    'bbox': (min_r, max_r, min_c, max_c),
                    'two': two_pos
                })

    # ------------------------------------------------------------------
    # 2. apply the transformation for each component
    # ------------------------------------------------------------------
    out = [row[:] for row in grid]      # work on a copy

